import{_ as e,o as a,c as i,a2 as t}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"Background compilation","description":"","frontmatter":{},"headers":[],"relativePath":"diagnostics/background-compilation.md","filePath":"diagnostics/background-compilation.md"}'),n={name:"diagnostics/background-compilation.md"};function s(r,o,l,c,d,p){return a(),i("div",null,[...o[0]||(o[0]=[t('<h1 id="background-compilation" tabindex="-1">Background compilation <a class="header-anchor" href="#background-compilation" aria-label="Permalink to &quot;Background compilation&quot;">​</a></h1><p>LazyVerilog reports diagnostics in two ways:</p><ol><li><strong>Fast diagnostics</strong> on every edit: syntax, preprocessor, and lint.</li><li><strong>Background compilation</strong>, off by default: a full slang elaboration that adds semantic diagnostics such as unknown modules, width mismatches, and type errors.</li></ol><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">[</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">compilation</span><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">]</span></span>\n<span class="line"><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">background_compilation </span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">=</span><span style="--shiki-light:#FE640B;--shiki-dark:#FAB387;"> true</span></span></code></pre></div><p>It can be slow on a weak machine, so enable it where you have the CPU and memory to spare.</p><h2 id="how-it-behaves" tabindex="-1">How it behaves <a class="header-anchor" href="#how-it-behaves" aria-label="Permalink to &quot;How it behaves&quot;">​</a></h2><ul><li>It starts 1.5 seconds after you stop typing, and only the newest edit is compiled.</li><li>It compiles the files in <code>[design].vcode</code> plus your open buffers, with your unsaved text, using the project&#39;s own <code>define</code> and <code>+incdir+</code> entries.</li><li>Each open project is compiled on its own, one after another, so memory stays at one project&#39;s worth. The setting is read per project.</li><li>Results appear for open files only. Requests such as hover never wait for it.</li><li>The worker runs at low priority on Linux. Worker count and the 1.5 second delay are fixed.</li></ul><h2 id="warnings-from-another-project-s-macros" tabindex="-1">Warnings from another project&#39;s macros <a class="header-anchor" href="#warnings-from-another-project-s-macros" aria-label="Permalink to &quot;Warnings from another project&#39;s macros&quot;">​</a></h2><p>A warning that slang raises while expanding a macro written in another project is not shown. One example is UVM&#39;s <code>`uvm_field_int</code> (implicit conversions inside UVM code). &quot;Another project&quot; means the macro&#39;s file belongs to a different <code>lazyverilog.toml</code> than the file the warning lands in, or to none at all. A warning on your own macro argument is dropped only when it also points into the library&#39;s body, such as an assignment to a variable the macro declares. A warning wholly inside your argument, such as the truncation in <code>`LIB_DO(n = w)</code>, is still shown.</p><ul><li>Errors from such macros are always shown.</li><li>A sibling project&#39;s macros count as foreign. A library vendored under your own <code>lazyverilog.toml</code>, such as a copy of UVM inside the project tree, does not, and its warnings are still shown. Give the library its own <code>lazyverilog.toml</code>, or keep it outside the project, to treat it as foreign.</li></ul>',10)])])}const m=e(n,[["render",s]]);export{u as __pageData,m as default};
